// CONFIG AFTER IMPORT
// 1) Put the public Render FastAPI URL. Example: https://ai-talapker-backend.onrender.com
const ASSISTANT_API_BASE = 'https://YOUR-RENDER-SERVICE.onrender.com';
// 2) Put Telegram bot token here, or replace this value with process/env handling in your n8n instance.
const TELEGRAM_BOT_TOKEN = 'PUT_TELEGRAM_BOT_TOKEN_HERE';

const update = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const msg = update.message || update.edited_message || (update.callback_query ? update.callback_query.message : null) || {};
const chatId = msg.chat?.id;
const userText = String((update.callback_query?.data ?? msg.text ?? msg.caption ?? '') || '').trim();

if (!chatId || !userText) {
  return [{ json: { validationError: true, reason: 'No Telegram chat_id or text in update.' } }];
}

const from = msg.from || update.callback_query?.from || {};
const sessionId = `telegram-${chatId}`;
const messageId = `tg-${msg.message_id || update.update_id || Date.now()}`;
const reply = msg.reply_to_message ? {
  id: `tg-${msg.reply_to_message.message_id}`,
  role: 'user',
  content: String(msg.reply_to_message.text || msg.reply_to_message.caption || '').slice(0, 1000),
  ts: msg.reply_to_message.date || null,
} : null;

return [{
  json: {
    validationError: false,
    chatId,
    telegramSendUrl: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
    assistantUrl: `${ASSISTANT_API_BASE.replace(/\/+$/, '')}/chat`,
    assistantRequest: {
      session_id: sessionId,
      message_id: messageId,
      message: userText,
      lang: 'ru',
      use_llm: true,
      allow_web_search: false,
      reply_to: reply,
    },
    telegramMeta: {
      update_id: update.update_id,
      chat_id: chatId,
      user_id: from.id || null,
      username: from.username || null,
      first_name: from.first_name || null,
      message_id: msg.message_id || null,
      source: update.callback_query ? 'callback_query' : (update.edited_message ? 'edited_message' : 'message'),
    },
  }
}];

const source = $items('Normalize Telegram Update')[0].json;
const status = Number($json.statusCode || 0);
const body = $json.body || {};
let answer = '';

if (status >= 200 && status < 300 && body && typeof body === 'object') {
  answer = String(body.answer || '').trim();
}
if (!answer) {
  answer = 'There is not enough information in the database to answer this question.';
}

// Telegram hard limit is 4096 chars. Keep margin for safety.
if (answer.length > 3900) {
  answer = answer.slice(0, 3850).trim() + '\n\n…';
}

return [{
  json: {
    telegramSendUrl: source.telegramSendUrl,
    telegramRequest: {
      chat_id: source.chatId,
      text: answer,
      disable_web_page_preview: true,
    },
    assistantStatus: status,
    assistantBody: body,
    meta: source.telegramMeta,
  }
}];
